import React, { useState } from 'react';
import './MenuForms.css'; // Importa tu archivo de estilos (renombrado o combinado con ExploreMenu.css)

const MenuForms = () => {
    const [selectedForm, setSelectedForm] = useState(null); // Estado para controlar qué opción mostrar

    // Función para seleccionar y mostrar el contenido adecuado
    const selectForm = (formType) => {
        setSelectedForm(formType);
    };

    return (
        <div className="explore-menu">
            <h2>¿En qué puede ayudarte FinanTec?</h2>
            <p className="explore-menu-text">
                Selecciona una de las siguientes opciones para comenzar. FinanTec está aquí para ayudarte a gestionar 
                tus finanzas y alcanzar tus objetivos financieros de manera eficiente.
            </p>
            <div className="explore-menu-list">
                {/* Generar Ahorro */}
                <div
                    className={`explore-menu-list-item ${selectedForm === 'save' ? 'active' : ''}`}
                    onClick={() => selectForm('save')}
                >
                    <img src="/path-to-your-icons/save-icon.png" alt="Generar Ahorro" />
                    <p>Generar Ahorro</p>
                </div>
                {/* Plan de Jubilación */}
                <div
                    className={`explore-menu-list-item ${selectedForm === 'retirement' ? 'active' : ''}`}
                    onClick={() => selectForm('retirement')}
                >
                    <img src="/path-to-your-icons/retirement-icon.png" alt="Plan de Jubilación" />
                    <p>Plan de Jubilación</p>
                </div>
                {/* Metas Largo/Corto Plazo */}
                <div
                    className={`explore-menu-list-item ${selectedForm === 'goal' ? 'active' : ''}`}
                    onClick={() => selectForm('goal')}
                >
                    <img src="/path-to-your-icons/goal-icon.png" alt="Metas Largo/Corto Plazo" />
                    <p>Metas Largo/Corto Plazo</p>
                </div>
            </div>

            <hr />

            {/* Mostrar contenido dependiendo de la opción seleccionada */}
            {selectedForm === 'save' && (
                <div className="info-section">
                    <h3>Generar Ahorro</h3>
                    <p>
                        El ahorro es una parte esencial de una planificación financiera saludable. Aquí te ayudamos a 
                        establecer un plan para alcanzar tus metas de ahorro. ¡Recuerda que cualquier cantidad que apartes puede 
                        marcar la diferencia a largo plazo!
                    </p>
                </div>
            )}
            {selectedForm === 'retirement' && (
                <div className="info-section">
                    <h3>Plan de Jubilación</h3>
                    <p>
                        Un plan de jubilación bien estructurado te permitirá disfrutar de la vida sin preocupaciones financieras
                        cuando llegue el momento de retirarte. ¡Comienza hoy a planificar tu futuro!
                    </p>
                </div>
            )}
            {selectedForm === 'goal' && (
                <div className="info-section">
                    <h3>Metas Largo/Corto Plazo</h3>
                    <p>
                        Ya sea que estés ahorrando para una casa, un coche o unas vacaciones, definir tus metas financieras 
                        es el primer paso para lograrlas. Nosotros te ayudamos a organizar tus ahorros para que cumplas con 
                        tus objetivos.
                    </p>
                </div>
            )}
        </div>
    );
}

export default MenuForms;
